#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <assert.h>
#include <time.h>
#include "../native/engine.h"
static double energy(short*p,int n){double e=0;for(int i=0;i<n;i++)e+=(double)p[i]*p[i];return e/n;}
static void u32(FILE*f,uint32_t n){for(int i=0;i<4;i++)fputc(n>>(8*i),f);}static void u16(FILE*f,uint16_t n){fputc(n&255,f);fputc(n>>8,f);}
int main(int argc,char**argv){assert(argc==4||argc==5);tsf*base=load_font(argv[1]);assert(base);base->sampleQuality=argc==5;tsf*a=copy_font(base,128),*b=copy_font(base,128);assert(a&&b);FILE*names=fopen(argv[2],"w");for(int i=0;i<base->presetNum;i++)fprintf(names,"%d\t%s\n",i,tsf_get_presetname(base,i));fclose(names);FX*fx=calloc(1,sizeof(FX));config_fx(fx,0,0,.8f,0,120,4,.6f);short pcm[256];float tmp[256];
 tsf_channel_set_presetindex(a,0,0);tsf_channel_note_on(a,0,60,.8f);double onset=0;for(int i=0;i<20;i++){render_audio(a,0,fx,1,0,pcm,128);onset+=energy(pcm,256);}assert(onset>100);panic_fx(a,b,fx);render_audio(a,b,fx,0,0,pcm,128);assert(energy(pcm,256)==0);
 tsf_channel_set_presetindex(a,0,0);tsf_channel_set_presetindex(b,0,0);tsf_channel_midi_control(a,0,64,127);tsf_channel_note_on(a,0,60,.8f);tsf_channel_note_on(b,0,60,.8f);for(int i=0;i<20;i++){tsf_render_float(a,tmp,128,0);tsf_render_float(b,tmp,128,0);}tsf_channel_note_off(a,0,60);tsf_channel_note_off(b,0,60);for(int i=0;i<500;i++){tsf_render_float(a,tmp,128,0);tsf_render_float(b,tmp,128,0);}assert(tsf_active_voice_count(a)>tsf_active_voice_count(b));tsf_channel_midi_control(a,0,64,0);for(int i=0;i<1500;i++)tsf_render_float(a,tmp,128,0);assert(tsf_active_voice_count(a)==0);
 panic_fx(a,b,fx);config_fx(fx,.8f,2,.8f,0,120,4,.6f);tsf_channel_set_presetindex(a,0,0);tsf_channel_note_on(a,0,60,1);for(int i=0;i<100;i++)render_audio(a,b,fx,.8f,0,pcm,128);double tail=0;for(int i=0;i<30;i++){render_audio(0,0,fx,0,0,pcm,128);tail+=energy(pcm,256);}assert(tail>100);panic_fx(a,b,fx);render_audio(0,0,fx,0,0,pcm,128);assert(energy(pcm,256)==0);
 int audible=0;for(int p=0;p<base->presetNum;p++){silence(a);tsf_channel_set_presetindex(a,0,p);tsf_channel_note_on(a,0,60,.8f);double e=0;for(int i=0;i<100;i++){render_audio(a,0,fx,.8f,0,pcm,128);e+=energy(pcm,256);}if(e>100)audible++;}
 panic_fx(a,b,fx);config_fx(fx,.3f,1,.8f,0,120,4,.6f);tsf_channel_set_presetindex(a,0,0);tsf_channel_set_presetindex(b,0,base->presetNum>89?89:0);int blocks=8*44100/128,peak=0;FILE*wav=fopen(argv[3],"wb");fwrite("RIFF",1,4,wav);u32(wav,36+blocks*128*4);fwrite("WAVEfmt ",1,8,wav);u32(wav,16);u16(wav,1);u16(wav,2);u32(wav,44100);u32(wav,176400);u16(wav,4);u16(wav,16);fwrite("data",1,4,wav);u32(wav,blocks*128*4);clock_t start=clock();for(int i=0;i<blocks;i++){if(i==0||i==690||i==1380){int n=i==0?60:i==690?57:65;for(int k=0;k<3;k++){int note=n+(k==1?4:k==2?7:0);tsf_channel_note_on(a,0,note,.7f);tsf_channel_note_on(b,0,note,.7f);}}if(i==2000){tsf_channel_note_off_all(a,0);tsf_channel_note_off_all(b,0);}render_audio(a,b,fx,.8f,.18f,pcm,128);for(int n=0;n<256;n++){int v=abs(pcm[n]);if(v>peak)peak=v;u16(wav,(uint16_t)pcm[n]);}}fclose(wav);assert(peak>1000&&peak<=32112);printf("PASS: loading, shared banks, audible notes, zero gain, sustain/release, reverb tail, panic, amplitude bounds.\nPresets: %d; audible at C4: %d; 8s audio rendered in %.3fs CPU; peak %d.\n",base->presetNum,audible,(double)(clock()-start)/CLOCKS_PER_SEC,peak);tsf_close(a);tsf_close(b);tsf_close(base);free(fx);return 0;
}
